function missingTicket(stubs) {
  const n = stubs.length
  let i = 0
  while (i < n) {
    const v = stubs[i]
    if (v < n && stubs[v] !== v) [stubs[i], stubs[v]] = [stubs[v], v]
    else i++
  }
  for (let k = 0; k < n; k++) if (stubs[k] !== k) return k
  return n
}

