def missing_ticket(stubs):
    n = len(stubs)
    i = 0
    while i < n:
        v = stubs[i]
        if v < n and stubs[v] != v:
            stubs[i], stubs[v] = stubs[v], v
        else:
            i += 1
    for k in range(n):
        if stubs[k] != k:
            return k
    return n
